 const rows=all.filter(b=>{if(own)return true;if(b.store)return retailStoreKey({[b.store]:true},store)!==null;if(Object.keys(e.by||{}).length===1)return true;return (/^JPS[- ]?\d+$/i.test(String(b.no||''))&&retailStoreKey({'DRJ Jaipur':true},store)!==null)||(/^R-\d+$/i.test(String(b.no||''))&&String(store).trim().toUpperCase()==='PTG')}).map(b=>({...b,store}));
 if(retailStoreKey({'DRJ Jaipur':true},store)!==null)for(const r of A(data.jaipurItemRows)||[]){if(r.d!==e.d||!/^JPS[- ]?\d+$/i.test(String(r.no||''))||rows.some(b=>b.no===r.no))continue;rows.push({no:r.no,store,amt:null,units:null,items:[],itemOnly:true})}
 return rows;
