 const groups=pgRangeRows(rows,'retail').map(g=>({...g,channel:'retail'})).sort((a,b)=>sourceRows?((b.amt.value??-Infinity)-(a.amt.value??-Infinity)):((b.qty.value??-Infinity)-(a.qty.value??-Infinity)));
 const q=tsQuery.trim().toLowerCase(),shown=groups.filter(g=>!q||[g.name,...g.members.map(r=>r.sku)].join(' ').toLowerCase().includes(q));
