/* Daily test prompts selected locally. No network calls or model service. */
const dailyIdeas=[
 ['fit-01','fit','retail','Make the fit difference visible.','Choose two stocked fits. Show the shoulder, sleeve and hem side by side.','Use one staff demonstration, then tally which fit shoppers try and buy. Keep price and placement steady.','Try-ons and purchases by fit; do not treat views as sales.'],
 ['fit-02','fit','online','Answer one sizing question before checkout.','Pick a recurring fit question and test one clearer product-page answer.','Check the exact product specification first. Change only the size guidance, then compare comparable traffic if tracking exists.','Size-related questions and returns, with conversion as context.'],
 ['fit-03','fit','retail','Test the tucked and untucked story.','Show one stocked shirt both ways instead of adding more styles to the rail.','Ask the team to record the styling shoppers choose. Keep the same product and price through the test.','Qualified try-ons and purchases, not staff preference.'],
 ['fit-04','fit','online','Show the detail a flat photo misses.','Film one short close-up of a verified product feature.','Confirm the material or construction claim in the specification. Test the detail video without changing the offer.','Product engagement, conversion and returns when available.'],
 ['pair-01','pairing','retail','Give one outfit a clear second piece.','Choose a stocked two-piece pairing and present it without an automatic discount.','Check both size runs and full selling prices. Tally paired baskets separately from ordinary single-item sales.','Contribution after costs, not basket value alone.'],
 ['pair-02','pairing','online','Test one occasion-led pairing.','Show one complete outfit for a specific occasion, with links to both exact variants.','Verify availability in the destination channel. Keep the edit small and do not imply proven buying affinity.','Paired clicks, purchases and returns if tracked.'],
 ['pair-03','pairing','retail','Find the missing piece in a real basket.','Review supplied itemised bills for one possible add-on test.','Use exact bill lines. One shared basket is a lead, not a pattern; ask the team to test the pairing before making it standard.','Paired-basket rate across comparable days.'],
 ['pair-04','pairing','online','Let the outfit explain the bundle.','Test a full-look image before changing the price.','Use existing verified items and current stock. Keep pricing unchanged so the creative test remains interpretable.','Outfit engagement and contribution, with stockouts noted.'],
 ['stock-01','stock','retail','Check the size behind the interest.','Start with a sold exact SKU, then verify its current availability.','Compare fresh sales and available-to-sell at the same store. Check transfers before a supplier order; leave quantity undecided without depth inputs.','Fewer verified size gaps without excess stock.'],
 ['stock-02','stock','online','Keep a promising edit shoppable.','Audit the exact variants in one featured outfit before sending it traffic.','Check current availability and channel listing status. Do not infer stock from sales or from a similarly named SKU.','Unavailable variant clicks and fulfilment misses.'],
 ['stock-03','stock','retail','Separate the stock gap from the display gap.','Compare a stocked low-visibility size with a visible size before changing buying depth.','Observe one rail and record enquiries. A quiet size may be hard to find; it is not automatically unwanted.','Try-ons and sales by exact size after the display test.'],
 ['stock-04','stock','online','Audit the slow item before discounting.','Choose one supplied slow-selling SKU and inspect its listing and availability.','Check image, size guidance, price basis and fulfilment information. Do not assume the product needs a lower price.','Verified listing issues and the outcome after one change.'],
 ['creative-01','creative','retail','Let one store question guide the next reel.','Ask the team for one repeated shopper question and answer it on camera.','Use a stocked product. Record the question without customer names; test one answer rather than a broad new campaign.','Useful enquiries, try-ons and purchases linked to the test.'],
 ['creative-02','creative','online','Test the first image, not five changes at once.','Compare one clearer full-look opening image with the existing image.','Check marketplace image rules. Keep price, title and audience stable where practical.','Conversion and returns by channel, if measured.'],
 ['creative-03','creative','retail','Make one rail a complete story.','Present a small stocked edit around one use, such as office or dinner.','Keep a comparison area unchanged. Ask staff to tally interest and purchases separately; note any other promotion.','The edit result against a comparable baseline.'],
 ['creative-04','creative','online','Turn one product detail into a useful answer.','Test a short fit or care explanation on one listing.','Use only verified specification and care information. Do not invent fabric or performance claims.','Questions answered, conversion and return reasons.'],
 ['economics-01','economics','retail','Check the offer before the poster.','Reconcile exact variant, tax and discount basis before fixed-price creative.','Compare dated store and public offers like for like. Different products or dates need not have equal prices.','One explainable price story, not a forced match.'],
 ['economics-02','economics','online','Judge the sale after its costs.','Compare a test using contribution when the required costs are available.','List missing fees, returns and fulfilment costs as unknown. Do not substitute revenue for profit.','Contribution and returns, without invented margins.'],
 ['economics-03','economics','retail','Test presentation before giving margin away.','Improve one counter presentation before proposing a discount.','Keep price unchanged. Record what changed and any stock constraints so the result can be interpreted.','Purchases and contribution on matched trading days.'],
 ['economics-04','economics','online','Separate channel results before scaling.','Review a small test channel by channel instead of dividing a combined total.','Use each source on its own basis. Missing product conversion or fees stay unknown.','A supported channel decision, not an equal budget split.'],
 ['site-01','expansion','research','Ask what one unit must earn.','Start the next-store case with a conservative unit model, not the mall headline.','Request actual rent, CAM, revenue share, deposit, fit-out and exit terms before calling a unit affordable. No outreach is started.','A model that can survive weaker footfall and higher costs.'],
 ['site-02','expansion','research','Count the right traffic on the visit.','Plan matched observation windows for one candidate frontage.','Separate passers-by, relevant interest and try-ons. Record weekday/weekend and timing; public mall footfall is not unit conversion.','Comparable unit evidence, not a lease recommendation.'],
 ['site-03','expansion','research','Use the existing store as the hurdle.','List what a candidate unit must improve on relative to an existing store.','Match operating hours, floor area and cost basis. Leave unknown inputs blank until verified.','A like-for-like case, not a forecast from one busy hour.'],
 ['site-04','expansion','research','Compare an alternative before choosing.','Put two candidate units through the same evidence checklist.','Use written terms and matched site observations. A research shortlist does not authorise a visit, spend or lease.','A decision with clear hold conditions and exit exposure.']
].map(([id,topic,lane,title,move,steps,measure])=>({id:'daily-'+id,topic,lane,title,move,steps,measure}));
function dailyTopic(key){if(key.startsWith('daily-'))return dailyIdeas.find(x=>x.id===key)?.topic||'';if(/^site-/.test(key))return 'expansion';if(/stock|size-check/.test(key))return 'stock';if(/gift|pair|wedding/.test(key))return 'pairing';if(/price/.test(key))return 'economics';if(/local-proof|diwali/.test(key))return 'creative';return 'fit'}
function dailyHash(s){let n=2166136261;for(const c of s){n^=c.charCodeAt(0);n=Math.imul(n,16777619)}return n>>>0}
function dailySelection(day=IST()){
 let state;try{state=JSON.parse(LS.getItem('dj_daily_mix_v1')||'null')}catch{}
 if(state?.day===day&&Array.isArray(state.ids)&&state.ids.length<=3&&state.ids.every(id=>dailyIdeas.some(x=>x.id===id)))return state;
 const choices=hiDeskState(),weights={};for(const [key,v] of Object.entries(choices)){const t=dailyTopic(key);if(t)weights[t]=(weights[t]||0)+(v.hidden?-2:v.saved?2:0)}
 const previous=state?.day&&state.day<day?state.ids||[]:[],candidates=dailyIdeas.filter(x=>!choices[x.id]?.hidden&&!previous.includes(x.id));
 const score=x=>Math.max(-4,Math.min(4,weights[x.topic]||0))+dailyHash(day+':'+x.id)/4294967296;
 const ranked=candidates.slice().sort((a,b)=>score(b)-score(a)),picked=[];const topics={};
 for(const x of ranked){if((topics[x.topic]||0)>=2)continue;picked.push(x);topics[x.topic]=(topics[x.topic]||0)+1;if(picked.length===2)break;}
 // One rotating exploration slot avoids turning a few saves into a closed loop.
 const rest=candidates.filter(x=>!picked.includes(x)&&!topics[x.topic]).sort((a,b)=>dailyHash(day+':explore:'+b.id)-dailyHash(day+':explore:'+a.id));
 if(rest[0])picked.push(rest[0]);else if(ranked.find(x=>!picked.includes(x)))picked.push(ranked.find(x=>!picked.includes(x)));
 const ids=picked.slice(0,3).map(x=>x.id),out={day,ids,previous,weights};LS.setItem('dj_daily_mix_v1',JSON.stringify(out));return out;
}
function dailyCards(){const mix=dailySelection(),choices=hiDeskState();return '<section id="hi-daily"><div class="hi-section-title"><small>TODAY / '+esc(mix.day)+' IST</small><h2>A small test for the next move.</h2><p>Three daily test prompts from a rotating library. Saves favour related topics tomorrow; Hides reduce them. This is not new web research or a forecast.</p></div>'+dailyIdeas.filter(x=>mix.ids.includes(x.id)||choices[x.id]?.saved||choices[x.id]?.hidden).map(x=>'<article class="hi-card" data-hi-kind="daily" data-hi-daily-id="'+x.id+'" data-hi-topic="'+x.topic+'" data-hi-daily-active="'+mix.ids.includes(x.id)+'"><div class="hi-kicker"><span>DAILY / '+esc(x.topic)+'</span><i>TEST</i></div><h2>'+esc(x.title)+'</h2><p class="hi-summary">'+esc(x.move)+'</p><div class="hi-effort">SMALL TEST / '+esc(x.lane==='research'?'Next store':x.lane==='retail'?'Retail':'Online')+'</div><p class="hi-visible-source">Selected '+esc(mix.day)+' IST. Planning prompt; verify the exact source before acting.</p><details><summary>Test method and evidence</summary><div class="hi-proof"><p>'+esc(x.steps)+'</p><p>Use the source read time shown in the app. Old or missing data cannot establish current stock, demand, margin or availability.</p></div><p class="hi-measure">Judge it by: '+esc(x.measure)+'</p></details></article>').join('')+'</section>'}
