const addD=(iso,k)=>new Date(Date.parse(iso+'T00:00:00Z')+k*864e5).toISOString().slice(0,10);
function calWin(full,iso,N){const by={},ambiguous=new Set();full.forEach(x=>{if(!x||!x.d)return;if(Object.prototype.hasOwnProperty.call(by,x.d)){ambiguous.add(x.d);by[x.d]=null}else by[x.d]=x});const dates=[];for(let k=N;k>=1;k--)dates.push(addD(iso,-k));const cur=dates.map(z=>by[z]).filter(Boolean),prev=[];for(let k=2*N;k>N;k--){const e=by[addD(iso,-k)];if(e)prev.push(e);}return {dates,by,cur,prev,ambiguous:[...ambiguous]};}
