function attn(chn){const o=chn!=='retail'?onStockRows():null,r=chn!=='online'?rtStockRows():null;const all=[...(o||[]),...(r||[])];if(!all.length)return null;
 const low=all.filter(x=>x.onHand!==null&&x.onHand<=3).sort((p,q)=>p.onHand-q.onHand||p.sku.localeCompare(q.sku));const soon=all.filter(x=>x.onHand>3&&x.days!==null&&x.days<=7).sort((p,q)=>p.days-q.days);return {low,soon};}
