 const H=A(chn==='online'?data.history:data.retailHistory);if(!H)return null;
 const cut=addD(IST(),-days),period=H.filter(e=>e.d>=cut&&e.d<IST()),covered=period.map(e=>itemsOf(e,chn)).filter(Boolean);
